def parse_grid(lines):
    grid = []
    for line in lines:
        grid.append(list(line))
    return grid

def is_square(grid, top_left, bottom_right):
    x1, y1 = top_left
    x2, y2 = bottom_right
    side_length = x2 - x1 + 1
    for i in range(x1, x2 + 1):
        if grid[y1][i] != '+' or grid[y2][i] != '+':
            return False
    for i in range(y1, y2 + 1):
        if grid[i][x1] != '+' or grid[i][x2] != '+':
            return False
    for i in range(x1 + 1, x2):
        for j in range(y1 + 1, y2):
            if grid[j][i] != '-':
                return False
    for i in range(y1 + 1, y2):
        for j in range(x1 + 1, x2):
            if grid[i][j] != '|':
                return False
    return True

def find_corners(grid):
    corners = []
    for i in range(len(grid)):
        for j in range(len(grid[i])):
            if grid[i][j] == '+':
                corners.append((i, j))
    return corners

def count_squares(lines):
    grid = [list(line) for line in lines]
    corners = find_corners(grid)
    count = 0
    for i in range(len(corners)):
        for j in range(i + 1, len(corners)):
            top_left = corners[i]
            bottom_right = corners[j]
            if is_square(grid, top_left, bottom_right):
                count += 1
    return count

