def map_numbers_to_letters(array):
    letter_map = {i + 1: chr(64 + i) for i in range(26)}
    letters = [letter_map[num] for num in array if 1 <= num <= 26]
    return letters

def check_for_bingo(letters):
    required_letters = set('BINGO')
    available_letters = set(map_numbers_to_letters(letters))
    return 'WIN' if required_letters.issubset(available_letters) else 'LOSE'

def bingo(array):
    letters = [chr(num + 64) for num in array]
    return 'WIN' if check_for_bingo(letters) else 'LOSE'

